<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{cerrarFase,descargarAsistencia,descargarDocumento,eliminarAsistencia,eliminarDocumento,obtenerSeguimiento,registrarAsistencia,subirDocumento}from'../services/territorial'
import type { AsistenciaFase, DocumentoFase, SeguimientoProceso } from '../interfaces/territorial.interface'
const props=defineProps<{id:string}>(),data=ref<SeguimientoProceso|null>(null),loading=ref(false),processing=ref(false),error=ref(''),success=ref(''),tab=ref<'documentos'|'asistencias'>('documentos'),documentOpen=ref(false),assistanceOpen=ref(false),closeOpen=ref(false),noCorrespond=ref(false)
const doc=reactive({fecha:new Date().toISOString().slice(0,10),nombre_archivo:'',archivo:null as File|null}),assistance=reactive({tipo_asistencia_id:0,fecha:new Date().toISOString().slice(0,10),detalle:'',archivo:null as File|null}),closing=ref('')
const processId=computed(()=>Number(props.id)),current=computed(()=>data.value?.fases.find(x=>x.estado==='actual')),progress=computed(()=>data.value?Math.round(data.value.fases.filter(x=>x.estado==='completada').length/data.value.fases.length*100):0)
async function load(){loading.value=true;error.value='';try{data.value=await obtenerSeguimiento(processId.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function pick(event:Event,target:'doc'|'assistance'){const file=(event.target as HTMLInputElement).files?.[0]||null;if(!file)return;const max=target==='doc'?15:10;if(file.size>max*1024*1024){error.value=`El archivo no debe superar ${max} MB.`;return}target==='doc'?doc.archivo=file:assistance.archivo=file}
async function saveDocument(){if(!doc.fecha||doc.nombre_archivo.trim().length<5||!doc.archivo){error.value='Complete fecha, nombre de al menos 5 caracteres y archivo.';return}processing.value=true;try{await subirDocumento(processId.value,{fecha:doc.fecha,nombre_archivo:doc.nombre_archivo,archivo:doc.archivo});success.value='Documento registrado.';documentOpen.value=false;await load()}catch(e){error.value=message(e)}finally{processing.value=false}}
async function saveAssistance(){if(!assistance.tipo_asistencia_id||!assistance.fecha||assistance.detalle.trim().length<5||!assistance.archivo){error.value='Complete el tipo, fecha, detalle y archivo de asistencia.';return}processing.value=true;try{await registrarAsistencia(processId.value,{...assistance,archivo:assistance.archivo});success.value='Asistencia registrada.';assistanceOpen.value=false;await load()}catch(e){error.value=message(e)}finally{processing.value=false}}
async function removeDoc(item:DocumentoFase){if(!confirm('¿Eliminar este documento?'))return;try{await eliminarDocumento(processId.value,item.id);await load()}catch(e){error.value=message(e)}}
async function removeAssistance(item:AsistenciaFase){if(!confirm('¿Eliminar esta asistencia?'))return;try{await eliminarAsistencia(processId.value,item.id);await load()}catch(e){error.value=message(e)}}
function openClose(skip=false){noCorrespond.value=skip;closing.value='';closeOpen.value=true}
async function closePhase(){if(closing.value.trim().length<3){error.value='Ingrese un comentario de al menos 3 caracteres.';return}processing.value=true;try{await cerrarFase(processId.value,closing.value,noCorrespond.value);success.value=noCorrespond.value?'Fase cerrada por no corresponder.':'Fase finalizada correctamente.';closeOpen.value=false;await load()}catch(e){error.value=message(e)}finally{processing.value=false}}
function message(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/modulos/integracion/territorial/procesos">← Procesos territoriales</RouterLink> / Seguimiento #{{id}}</nav><div v-if="error" class="flash bad">{{error}}</div><div v-if="success" class="flash good">✓ {{success}}</div><div v-if="loading" class="empty">Cargando seguimiento…</div><template v-else-if="data"><header class="hero"><div class="mark">IT</div><div><small>PROCESO #{{data.proceso.id}} · {{data.proceso.fecha}}</small><h1>{{data.proceso.centro_poblado}}</h1><p>{{data.proceso.empresa}} · {{data.proceso.distrito}}, {{data.proceso.provincia}}</p></div><div class="advance"><b>{{progress}}%</b><span>{{data.proceso.fase}}</span></div></header><section class="timeline"><article v-for="(phase,index) in data.fases" :key="phase.id" :class="phase.estado"><i>{{phase.estado==='completada'?'✓':index+1}}</i><div><b>{{phase.nombre}}</b><small>{{phase.estado==='completada'?(phase.fecha_cierre||'Finalizada'):phase.estado==='actual'?'Fase actual':'Pendiente'}}</small></div></article></section><section v-if="current" class="workspace"><header><div><small>FASE ACTUAL</small><h2>{{current.nombre}}</h2></div><button @click="openClose(true)">No corresponde</button><button @click="openClose(false)">Finalizar fase</button></header><div class="tabs"><button :class="{active:tab==='documentos'}" @click="tab='documentos'">Documentos ({{current.documentos.length}})</button><button :class="{active:tab==='asistencias'}" @click="tab='asistencias'">Asistencias ({{current.asistencias.length}})</button></div><div v-if="tab==='documentos'"><div class="section-head"><p>Para finalizar una fase debe existir al menos un documento.</p><button @click="documentOpen=true">+ Agregar documento</button></div><div v-if="!current.documentos.length" class="empty inner">No existen documentos en esta fase.</div><div class="records"><article v-for="item in current.documentos" :key="item.id"><span>DOC</span><div><b>{{item.nombre_archivo}}</b><small>{{item.fecha}} · {{item.usuario||'Usuario del sistema'}}</small></div><button @click="descargarDocumento(processId,item)">Descargar</button><button class="delete" @click="removeDoc(item)">Eliminar</button></article></div></div><div v-else><div class="section-head"><p>Actividades de acompañamiento realizadas durante la fase.</p><button @click="assistanceOpen=true">+ Registrar asistencia</button></div><div v-if="!current.asistencias.length" class="empty inner">No existen asistencias en esta fase.</div><div class="records"><article v-for="item in current.asistencias" :key="item.id"><span>AS</span><div><b>{{item.tipo_asistencia}}</b><small>{{item.fecha}} · {{item.detalle}}</small></div><button @click="descargarAsistencia(processId,item)">Descargar</button><button class="delete" @click="removeAssistance(item)">Eliminar</button></article></div></div></section></template><div v-if="documentOpen" class="backdrop"><form class="modal" @submit.prevent="saveDocument"><header><h2>Agregar documento</h2><button type="button" @click="documentOpen=false">×</button></header><label>Fecha *<input v-model="doc.fecha" type="date"></label><label>Nombre del documento *<input v-model.trim="doc.nombre_archivo"></label><label>Archivo (máx. 15 MB) *<input type="file" @change="pick($event,'doc')"></label><footer><button type="button" class="clear" @click="documentOpen=false">Cancelar</button><button :disabled="processing">Guardar</button></footer></form></div><div v-if="assistanceOpen" class="backdrop"><form class="modal" @submit.prevent="saveAssistance"><header><h2>Registrar asistencia</h2><button type="button" @click="assistanceOpen=false">×</button></header><label>Tipo *<select v-model.number="assistance.tipo_asistencia_id"><option :value="0">Seleccione</option><option v-for="item in data?.tipos_asistencia" :key="item.id" :value="item.id">{{item.nombre}}</option></select></label><label>Fecha *<input v-model="assistance.fecha" type="date"></label><label>Detalle *<textarea v-model.trim="assistance.detalle" rows="3"></textarea></label><label>Archivo (máx. 10 MB) *<input type="file" @change="pick($event,'assistance')"></label><footer><button type="button" class="clear" @click="assistanceOpen=false">Cancelar</button><button :disabled="processing">Guardar</button></footer></form></div><div v-if="closeOpen" class="backdrop"><form class="modal" @submit.prevent="closePhase"><header><h2>{{noCorrespond?'Cerrar por no corresponder':'Finalizar fase'}}</h2><button type="button" @click="closeOpen=false">×</button></header><p class="warning">{{noCorrespond?'Solo puede usarse cuando la fase no tiene documentos.':'La fase debe tener al menos un documento registrado.'}}</p><label>Comentario del hito *<textarea v-model.trim="closing" rows="4"></textarea></label><footer><button type="button" class="clear" @click="closeOpen=false">Cancelar</button><button :disabled="processing">Confirmar cierre</button></footer></form></div></div></template>
<style scoped>.page{--a:#148f92;color:#35474d}nav{margin-bottom:15px;font-size:.68rem}nav a{color:var(--a)}.flash{padding:10px;font-size:.58rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.hero{padding:20px 24px;display:flex;align-items:center;gap:13px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small,.workspace small{color:var(--a);font-size:.45rem}.hero h1{margin:2px 0;font-size:1.2rem}.hero p{margin:0;color:#7d898f;font-size:.58rem}.advance{margin-left:auto;text-align:right}.advance b,.advance span{display:block}.advance b{font-size:1rem}.advance span{font-size:.44rem}.timeline{margin:13px 0;display:flex;overflow:auto;background:#fff}.timeline article{min-width:135px;padding:12px;display:flex;align-items:center;gap:7px;border-right:1px solid #e7eced;opacity:.5}.timeline article.current,.timeline article.completada{opacity:1}.timeline i{width:25px;height:25px;display:grid;place-items:center;border-radius:50%;background:#e7eded;font-size:.43rem;font-style:normal}.timeline .completada i{color:#fff;background:var(--a)}.timeline .current i{color:#fff;background:#e19b33}.timeline b,.timeline small{display:block;font-size:.43rem}.timeline small{color:#89959a;font-size:.36rem}.workspace{background:#fff}.workspace>header{padding:15px;display:flex;align-items:center;gap:7px;border-bottom:1px solid #e5eaeb}.workspace h2{margin:2px 0;font-size:.75rem}.workspace header div{margin-right:auto}.workspace button,.modal footer button,.section-head button{padding:7px 9px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.43rem}.tabs{display:flex;border-bottom:1px solid #e4e9ea}.tabs button{padding:11px;color:#748187;background:none;border-radius:0}.tabs button.active{color:var(--a);border-bottom:2px solid var(--a)}.section-head{padding:12px 15px;display:flex;align-items:center}.section-head p{margin:0;color:#7d898f;font-size:.45rem}.section-head button{margin-left:auto}.records article{padding:10px 15px;display:grid;grid-template-columns:35px 1fr auto auto;align-items:center;gap:9px;border-top:1px solid #edf0f1;font-size:.44rem}.records article>span{width:32px;height:32px;display:grid;place-items:center;border-radius:6px;color:var(--a);background:#e5f4f4;font-weight:800}.records b,.records small{display:block}.records small{color:#879399}.records .delete{color:#a13e43;background:none}.empty{padding:45px;text-align:center;background:#fff;font-size:.56rem}.empty.inner{padding:28px;background:#fafbfb}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(520px,100%);padding:20px;border-radius:11px;background:#fff}.modal>header{display:flex}.modal h2{margin:0;font-size:.82rem}.modal>header button{margin-left:auto;border:0;background:none;font-size:1.3rem}.modal label{display:block;margin-top:12px;font-size:.46rem}input,select,textarea{width:100%;padding:8px;border:1px solid #d8e0e3;border-radius:5px;font:inherit;font-size:.5rem}.modal footer{margin-top:14px;display:flex;justify-content:flex-end;gap:5px}.clear{color:#68767c!important;background:#edf1f2!important}.warning{padding:9px;color:#795d20;background:#fff4d8;font-size:.46rem}@media(max-width:600px){.hero,.workspace>header{flex-wrap:wrap}.advance{margin-left:0}.records article{grid-template-columns:35px 1fr}}</style>
